#include "impedance.h"
#include "main.h"

#include <math.h>
#include <stddef.h>

/*
 * Handles generated by CubeMX.
 */
extern ADC_HandleTypeDef hadc1;
extern DAC_HandleTypeDef hdac;
extern TIM_HandleTypeDef htim6;


/* =========================================================
 * DAC SINE TABLE
 * ========================================================= */

static uint32_t sine_table[IMPEDANCE_SINE_SAMPLES];


/* =========================================================
 * ADC BUFFER
 * ========================================================= */

static uint16_t adc_buffer[IMPEDANCE_ADC_SAMPLES];

static volatile uint8_t adc_conversion_done = 0;


/* =========================================================
 * GENERATE SINE TABLE
 * ========================================================= */

static void Impedance_GenerateSineTable(void)
{
    for (uint32_t i = 0;
         i < IMPEDANCE_SINE_SAMPLES;
         i++)
    {
        float angle =
            (2.0f * 3.14159265359f * (float)i) /
            (float)IMPEDANCE_SINE_SAMPLES;

        float sine_value = sinf(angle);

        float dac_value =
            (float)IMPEDANCE_DAC_MIDPOINT +
            ((float)IMPEDANCE_DAC_AMPLITUDE *
             sine_value);

        if (dac_value < 0.0f)
        {
            dac_value = 0.0f;
        }

        if (dac_value > 4095.0f)
        {
            dac_value = 4095.0f;
        }

        sine_table[i] = (uint32_t)dac_value;
    }
}


/* =========================================================
 * INITIALIZATION
 * ========================================================= */

HAL_StatusTypeDef Impedance_Init(void)
{
    /*
     * Generate the 1 kHz sine-wave lookup table.
     */
    Impedance_GenerateSineTable();

    /*
     * Make sure the excitation timer is stopped
     * during initialization.
     */
    HAL_TIM_Base_Stop(&htim6);

    /*
     * Make sure any previous DAC DMA operation is stopped.
     */
    HAL_DAC_Stop_DMA(
        &hdac,
        DAC_CHANNEL_1
    );

    /*
     * Start DAC channel 1 without DMA.
     *
     * Set the output to the DC midpoint until
     * Impedance_Measure() starts the excitation.
     */
    if (HAL_DAC_Start(
            &hdac,
            DAC_CHANNEL_1
        ) != HAL_OK)
    {
        return HAL_ERROR;
    }

    HAL_DAC_SetValue(
        &hdac,
        DAC_CHANNEL_1,
        DAC_ALIGN_12B_R,
        IMPEDANCE_DAC_MIDPOINT
    );

    return HAL_OK;
}

/* =========================================================
 * START EXCITATION
 * ========================================================= */

HAL_StatusTypeDef Impedance_StartExcitation(void)
{
    /*
     * Reset timer so the sine table always starts
     * from the same point.
     */
    __HAL_TIM_SET_COUNTER(&htim6, 0);

    /*
     * Start DAC DMA.
     */
    if (HAL_DAC_Start_DMA(
            &hdac,
            DAC_CHANNEL_1,
            sine_table,
            IMPEDANCE_SINE_SAMPLES,
            DAC_ALIGN_12B_R) != HAL_OK)
    {
        return HAL_ERROR;
    }

    /*
     * Start TIM6.
     *
     * TIM6 TRGO now triggers DAC updates.
     */
    if (HAL_TIM_Base_Start(&htim6) != HAL_OK)
    {
        HAL_DAC_Stop_DMA(
            &hdac,
            DAC_CHANNEL_1
        );

        return HAL_ERROR;
    }

    return HAL_OK;
}


/* =========================================================
 * STOP EXCITATION
 * ========================================================= */

void Impedance_StopExcitation(void)
{
    HAL_TIM_Base_Stop(&htim6);

    HAL_DAC_Stop_DMA(
        &hdac,
        DAC_CHANNEL_1
    );

    /*
     * Return DAC output to midpoint.
     */
    HAL_DAC_Start(
        &hdac,
        DAC_CHANNEL_1
    );

    HAL_DAC_SetValue(
        &hdac,
        DAC_CHANNEL_1,
        DAC_ALIGN_12B_R,
        IMPEDANCE_DAC_MIDPOINT
    );
}


/* =========================================================
 * SINGLE ADC READING
 * ========================================================= */

float Impedance_ReadADCVoltage(void)
{
    uint32_t adc_value = 0;

    if (HAL_ADC_Start(&hadc1) != HAL_OK)
    {
        return 0.0f;
    }

    if (HAL_ADC_PollForConversion(
            &hadc1,
            10) != HAL_OK)
    {
        HAL_ADC_Stop(&hadc1);

        return 0.0f;
    }

    adc_value = HAL_ADC_GetValue(&hadc1);

    HAL_ADC_Stop(&hadc1);

    return
        ((float)adc_value * 3.3f) /
        4095.0f;
}


/* =========================================================
 * IMPEDANCE MEASUREMENT
 * ========================================================= */

HAL_StatusTypeDef Impedance_Measure(
    ImpedanceResult_t *result)
{
    if (result == NULL)
    {
        return HAL_ERROR;
    }

    adc_conversion_done = 0;

    /*
     * Clear ADC buffer.
     */
    for (uint32_t i = 0;
         i < IMPEDANCE_ADC_SAMPLES;
         i++)
    {
        adc_buffer[i] = 0;
    }

    /*
     * Start 1 kHz excitation.
     */
    if (Impedance_StartExcitation() != HAL_OK)
    {
        return HAL_ERROR;
    }

    /*
     * Allow analog circuit to settle.
     */
    HAL_Delay(20);

    /*
     * Start ADC DMA.
     *
     * IMPORTANT:
     * ADC must be configured in CubeMX for
     * continuous conversion + DMA.
     */
    if (HAL_ADC_Start_DMA(
            &hadc1,
            (uint32_t *)adc_buffer,
            IMPEDANCE_ADC_SAMPLES) != HAL_OK)
    {
        Impedance_StopExcitation();

        return HAL_ERROR;
    }

    /*
     * Wait until DMA fills the buffer.
     *
     * Timeout prevents the program from getting stuck
     * if ADC DMA hasn't been configured correctly.
     */
    uint32_t start_time = HAL_GetTick();

    while (!adc_conversion_done)
    {
        if ((HAL_GetTick() - start_time) > 100)
        {
            HAL_ADC_Stop_DMA(&hadc1);

            Impedance_StopExcitation();

            return HAL_TIMEOUT;
        }
    }

    HAL_ADC_Stop_DMA(&hadc1);

    /*
     * Stop excitation.
     */
    Impedance_StopExcitation();


    /* =====================================================
     * CALCULATE DC + RMS
     * ===================================================== */

    float sum = 0.0f;

    for (uint32_t i = 0;
         i < IMPEDANCE_ADC_SAMPLES;
         i++)
    {
        sum += (float)adc_buffer[i];
    }

    float mean =
        sum / (float)IMPEDANCE_ADC_SAMPLES;


    /*
     * Convert mean ADC count to voltage.
     */
    float dc_voltage =
        (mean * 3.3f) / 4095.0f;


    /*
     * Calculate AC RMS after removing DC offset.
     */
    float square_sum = 0.0f;

    for (uint32_t i = 0;
         i < IMPEDANCE_ADC_SAMPLES;
         i++)
    {
        float centered =
            (float)adc_buffer[i] - mean;

        square_sum +=
            centered * centered;
    }

    float ac_rms_counts =
        sqrtf(
            square_sum /
            (float)IMPEDANCE_ADC_SAMPLES
        );

    float ac_rms_voltage =
        (ac_rms_counts * 3.3f) /
        4095.0f;


    /*
     * Store result.
     */
    result->dc_voltage =
        dc_voltage;

    result->rms_voltage =
        sqrtf(
            (dc_voltage * dc_voltage) +
            (ac_rms_voltage * ac_rms_voltage)
        );

    result->ac_rms_voltage =
        ac_rms_voltage;

    result->frequency_hz =
        IMPEDANCE_FREQUENCY_HZ;


    return HAL_OK;
}


/* =========================================================
 * ADC DMA COMPLETE CALLBACK
 * ========================================================= */

void HAL_ADC_ConvCpltCallback(
    ADC_HandleTypeDef *hadc)
{
    if (hadc->Instance == ADC1)
    {
        adc_conversion_done = 1;
    }
}
